blocks.content:
1/* Import custom font */
2@import url("https://fonts.googleapis.com/css2?family=Euclid+Circular+A:wght@400;500&display=swap");
3
4* {
5    font-family: 'Euclid Circular A', sans-serif;
6    line-height: 1.5;
7}
8
9.projects-grid {
10    display: grid;
11    grid-template-columns: 2fr 1fr 1fr;
12    grid-template-rows: auto auto;
13    gap: 20px;
14}
15
16/* Style cards */
17.projects-grid > div {
18    background-color: #fff;
19    border-radius: 10px;
20    padding: 20px;
21    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
22}
23
24.primary-card {
25    grid-area: 1 / 1 / 3 / 2;
26}
27
28/* Flex layout */
29.tech-tag-list {
30    display: flex;
31    gap: 10px;
32    margin-bottom: 10px;
33}
34
35/* Style tags */
36.tech-tag-list > div {
37    background-color: #f3f3f3;
38    color: #49497e;
39    font-size: 0.8rem;
40    border-radius: 5px;
41    padding: 4px 4px;
42}
43
44/* Style images */
45img {
46    width: 100%;
47    border-radius: 10px;
48}
49
50/* Style headings */
51h3 {
52    color: #25265e;
53    font-size: 1.5rem;
54    font-weight: 550;
55}
56
57/* Style paragraphs */
58p {
59    font-size: 16px;
60}
61
62/* Style links */
63a {
64    color: #0556f3;
65    font-weight: medium;
66    text-decoration: none;
67}
